{

"kind": "propose",
"summary": "Liveness probe timeout is too short, causing premature termination during startup",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Liveness probe timeout of 1s is insufficient for app startup",
    "supporting": ["probe_kills", "killed_during_startup", "ev-container_logs_tail"],
    "contradicting": ["probe_timeouts"],
    "missing": ["actual_app_start_latency"],
    "status": "supported"
  },
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "App starts but probes fail before it's ready",
    "supporting": ["killed_during_startup", "ev-container_logs_tail"],
    "contradicting": ["crashed_on_its_own"],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "finance",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 10
    }
  },
  "expected_effect": "Increase liveness probe timeout to 10s to match app startup duration",
  "rationale": "Logs show app took >1s to start but liveness probe failed immediately. Increasing timeout to 10s allows app to initialize before probe fails. No evidence of application bugs or dependency failures. Readiness probe should not be adjusted as app is not serving traffic yet.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["probe_kills", "killed_during_startup", "crashed_on_its_own"]
}
}
